:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --accent: #41a6f6;
  --text: #f4f4f4;
  --muted: #94b0c2;
  --done: #566c86;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 24px 20px;
  box-shadow: 8px 8px 0 #0d0f1a;
}
h1 {
  margin: 0 0 12px;
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}
.stats {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
  font-size: 0.95rem;
  color: var(--muted);
}
.stats strong { color: var(--text); }
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
input[type="text"] {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font-size: 1rem;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--muted);
  border-radius: 0;
  outline: none;
}
input[type="text"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}
button {
  font-family: inherit;
  font-size: 1rem;
  cursor: pointer;
  border: 3px solid var(--accent);
  border-radius: 0;
  background: var(--accent);
  color: var(--bg);
  padding: 10px 16px;
  font-weight: 700;
  text-transform: uppercase;
  transition: transform 0.05s, background 0.15s;
}
button:hover { background: #6bb8f8; }
button:active { transform: translate(2px, 2px); }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg);
  border: 3px solid var(--muted);
  padding: 10px 12px;
}
.todo-item.done .todo-text {
  text-decoration: line-through;
  color: var(--done);
}
.todo-text {
  flex: 1;
  word-break: break-word;
  font-size: 1rem;
}
.todo-item input[type="checkbox"] {
  width: 22px;
  height: 22px;
  accent-color: var(--accent);
  cursor: pointer;
}
.todo-item button {
  padding: 6px 10px;
  font-size: 0.85rem;
  background: transparent;
  color: var(--accent);
  border-color: var(--accent);
}
.todo-item button:hover { background: var(--accent); color: var(--bg); }
.empty {
  text-align: center;
  color: var(--muted);
  font-size: 0.95rem;
  margin: 8px 0 0;
}
.empty.hidden { display: none; }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 18px 14px; }
  h1 { font-size: 1.3rem; }
  .input-row { flex-direction: column; }
  .input-row button { width: 100%; }
}

(function () {
  'use strict';

  var tasks = [];
  var nextId = 1;

  var input = document.getElementById('todo-input');
  var addBtn = document.getElementById('todo-add');
  var form = document.getElementById('todo-form');
  var list = document.getElementById('todo-list');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');
  var emptyMsg = document.getElementById('empty-msg');

  function updateCounts() {
    totalEl.textContent = String(tasks.length);
    var incomplete = tasks.filter(function (t) { return !t.done; }).length;
    remainingEl.textContent = String(incomplete);
    emptyMsg.classList.toggle('hidden', tasks.length > 0);
  }

  function renderTask(task) {
    var li = document.createElement('li');
    li.className = 'todo-item' + (task.done ? ' done' : '');
    li.dataset.id = String(task.id);

    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'todo-check-' + task.id;
    checkbox.checked = task.done;
    checkbox.setAttribute('aria-label', 'Mark task ' + task.id + ' complete');
    checkbox.addEventListener('change', function () {
      task.done = checkbox.checked;
      li.classList.toggle('done', task.done);
      updateCounts();
    });

    var span = document.createElement('span');
    span.className = 'todo-text';
    span.id = 'todo-text-' + task.id;
    span.textContent = task.text;

    var del = document.createElement('button');
    del.type = 'button';
    del.id = 'todo-delete-' + task.id;
    del.textContent = 'Delete';
    del.setAttribute('aria-label', 'Delete task ' + task.id);
    del.addEventListener('click', function () {
      tasks = tasks.filter(function (t) { return t.id !== task.id; });
      li.remove();
      updateCounts();
    });

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(del);
    list.appendChild(li);
  }

  function addTask() {
    var text = input.value.trim();
    if (!text) return;
    var task = { id: nextId, text: text, done: false };
    nextId += 1;
    tasks.push(task);
    renderTask(task);
    input.value = '';
    input.focus();
    updateCounts();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    addTask();
  });

  addBtn.addEventListener('click', function (e) {
    e.preventDefault();
    addTask();
  });

  updateCounts();
})();
